  (v_cables, v_cables_dom, 'demo-domestic-cable-1-5sqmm', '1.5 sqmm Copper Wire (90m Roll)', 'Light-duty PVC copper wire for lighting circuits', 'PVC insulated single-core copper wire for residential lighting circuits. 90-metre roll. ISI-marked.', 'https://images.pexels.com/photos/3615731/pexels-photo-3615731.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2400, 'per roll', 'unit', 1, 1, 50, '{"conductor": "Copper", "insulation": "PVC", "voltage_rating": "1100V", "standard": "IS 694"}'::jsonb, 'delivery', true, 20, 18, 5, true),
  (v_cables, v_cables_dom, 'demo-domestic-flexible-cable', '3-core Flexible Cable 1.5 sqmm (30m)', 'Flexible cable for appliances and extension boards', '3-core PVC flexible cable suitable for connecting appliances, extension boards, and temporary power needs. 30-metre length.', 'https://images.pexels.com/photos/3615731/pexels-photo-3615731.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 950, 'per piece', 'unit', 1, 1, 100, '{"conductor": "Copper", "cores": "3", "insulation": "PVC"}'::jsonb, 'delivery', true, 30, 40, 10, true),
  (v_cables, v_cables_dom, 'demo-domestic-coaxial-cable', 'Coaxial Cable RG6 (100m Roll)', 'TV/satellite signal cable with copper conductor', 'RG6 coaxial cable for television and satellite signal distribution. 100-metre roll with copper-clad steel conductor.', 'https://images.pexels.com/photos/28286039/pexels-photo-28286039.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1800, 'per roll', 'unit', 1, 1, 30, '{"type": "RG6", "length": "100m", "conductor": "Copper-clad steel"}'::jsonb, 'delivery', true, 40, 12, 3, true),
  (v_cables, v_cables_dom, 'demo-domestic-cat6-cable', 'Cat6 Ethernet Cable (305m Box)', 'High-speed network cable for internet and LAN', 'Cat6 UTP ethernet cable in a 305-metre pull box. Suitable for gigabit network installations. Pure copper conductor.', 'https://images.pexels.com/photos/28286039/pexels-photo-28286039.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4500, 'per box', 'unit', 1, 1, 20, '{"category": "Cat6", "type": "UTP", "length": "305m", "conductor": "Pure copper"}'::jsonb, 'delivery', true, 50, 8, 2, true);
