  (v_cables, v_cables_ind, 'demo-industrial-armoured-cable-4core', '4-Core Armoured Cable 4 sqmm (Per Metre)', 'XLPE insulated steel wire armoured cable for industrial power', '4-core XLPE insulated, steel wire armoured (SWA) cable for industrial power distribution. Sold by the metre. Conforms to IS 7098.', 'https://images.pexels.com/photos/29596327/pexels-photo-29596327.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 285, 'per metre', 'length', 1, 0.5, 500, '{"conductor": "Aluminium", "insulation": "XLPE", "armour": "SWA", "cores": "4", "standard": "IS 7098"}'::jsonb, 'delivery', true, 10, 300, 50, true),
  (v_cables, v_cables_ind, 'demo-industrial-control-cable-7core', '7-Core Control Cable 1.5 sqmm (Per Metre)', 'Multi-core control cable for instrumentation and control circuits', '7-core PVC insulated control cable for industrial control and instrumentation circuits. Sold by the metre.', 'https://images.pexels.com/photos/29596327/pexels-photo-29596327.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 145, 'per metre', 'length', 1, 0.5, 1000, '{"conductor": "Copper", "cores": "7", "insulation": "PVC", "area": "1.5 sqmm"}'::jsonb, 'delivery', true, 20, 200, 30, true),
  (v_cables, v_cables_ind, 'demo-industrial-power-cable-3-5core', '3.5-Core Power Cable 240 sqmm (Per Metre)', 'High-capacity aluminium power cable for heavy loads', '3.5-core aluminium conductor XLPE insulated power cable for high-current industrial applications. Sold by the metre.', 'https://images.pexels.com/photos/29596327/pexels-photo-29596327.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1200, 'per metre', 'length', 1, 1, 200, '{"conductor": "Aluminium", "insulation": "XLPE", "cores": "3.5", "area": "240 sqmm"}'::jsonb, 'delivery', true, 30, 45, 10, true),
