  (v_lights, v_lights_dom, 'demo-led-bulb-9w', 'LED Bulb 9W Cool White', 'Energy-efficient LED bulb with B22 base', '9-watt LED bulb with B22 base, cool white (6500K) light output. 80% more efficient than incandescent. Long life of 25,000 hours.', 'https://images.pexels.com/photos/8357326/pexels-photo-8357326.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 120, 'per piece', 'unit', 1, 1, 200, '{"wattage": "9W", "base": "B22", "color_temp": "6500K", "lumen": "810", "life": "25000 hrs"}'::jsonb, 'pickup', true, 10, 50, 10, true),
  (v_lights, v_lights_dom, 'demo-led-bulb-12w-warm', 'LED Bulb 12W Warm White', 'Warm white LED bulb for living spaces', '12-watt LED bulb with B22 base, warm white (3000K) light. Ideal for living rooms and bedrooms. 25,000 hour life.', 'https://images.pexels.com/photos/8357326/pexels-photo-8357326.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 150, 'per piece', 'unit', 1, 1, 200, '{"wattage": "12W", "base": "B22", "color_temp": "3000K", "lumen": "1080", "life": "25000 hrs"}'::jsonb, 'pickup', true, 20, 30, 8, true),
  (v_lights, v_lights_dom, 'demo-led-panel-light-18w', 'LED Ceiling Panel 18W Round', 'Slim recessed LED panel for modern ceilings', '18-watt round LED ceiling panel with slim profile. Recessed mount. Cool white light. Suitable for kitchens, offices, and corridors.', 'https://images.pexels.com/photos/12092231/pexels-photo-12092231.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 480, 'per piece', 'unit', 1, 1, 50, '{"wattage": "18W", "shape": "Round", "mount": "Recessed", "color_temp": "6500K", "lumen": "1620"}'::jsonb, 'pickup', true, 30, 22, 5, true),
  (v_lights, v_lights_dom, 'demo-decorative-pendant-light', 'Decorative Pendant Light Fixture', 'Stylish pendant lamp for dining and living areas', 'Modern decorative pendant light fixture with metal shade. Suitable for dining tables and entryways. E27 holder (bulb not included).', 'https://images.pexels.com/photos/12092231/pexels-photo-12092231.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1200, 'per piece', 'unit', 1, 1, 20, '{"type": "Pendant", "holder": "E27", "material": "Metal", "bulb_included": "No"}'::jsonb, 'pickup', true, 40, 0, 3, true);
