  (v_lights, v_lights_ind, 'demo-highbay-led-100w', 'LED High-Bay Light 100W', 'High-lumen LED high-bay for warehouses and factories', '100-watt LED high-bay light with 120-degree beam angle. Suitable for warehouses, factories, and large retail spaces. IP65 rated.', 'https://images.pexels.com/photos/19881986/pexels-photo-19881986.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2800, 'per piece', 'unit', 1, 1, 30, '{"wattage": "100W", "beam_angle": "120 deg", "ip_rating": "IP65", "lumen": "12000", "mount": "Suspension"}'::jsonb, 'pickup', true, 10, 15, 3, true),
  (v_lights, v_lights_ind, 'demo-flood-light-50w', 'LED Flood Light 50W', 'Outdoor LED flood light with IP66 rating', '50-watt LED flood light for outdoor area lighting. IP66 weatherproof. Cool white. Suitable for building exteriors and open yards.', 'https://images.pexels.com/photos/19881986/pexels-photo-19881986.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 850, 'per piece', 'unit', 1, 1, 50, '{"wattage": "50W", "ip_rating": "IP66", "color_temp": "6500K", "lumen": "5000"}'::jsonb, 'pickup', true, 20, 28, 5, true),
  (v_lights, v_lights_ind, 'demo-batten-light-20w', 'LED Batten Light 20W (4ft)', 'Linear LED batten for workshops and garages', '4-foot LED batten light, 20 watts. Replaces traditional tube lights. Linkable design. Cool white. For workshops, garages, and utility areas.', 'https://images.pexels.com/photos/19881986/pexels-photo-19881986.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 420, 'per piece', 'unit', 1, 1, 80, '{"wattage": "20W", "length": "4 ft", "color_temp": "6500K", "lumen": "2000", "linkable": "Yes"}'::jsonb, 'pickup', true, 30, 6, 2, true);
