  (v_lights, v_fans, 'demo-ceiling-fan-1200mm', 'Ceiling Fan 1200mm (48 inch)', 'High-speed ceiling fan with 3 blades', '1200mm sweep ceiling fan with high-speed motor, 3 aerodynamic blades. Suitable for living rooms and bedrooms. ISI-marked motor with 2-year warranty.', 'https://images.pexels.com/photos/4224023/pexels-photo-4224023.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1450, 'per piece', 'unit', 1, 1, 40, '{"sweep": "1200mm", "blades": "3", "speed": "High", "warranty": "2 years", "motor": "Copper"}'::jsonb, 'pickup', true, 10, 20, 5, true),
  (v_lights, v_fans, 'demo-ceiling-fan-with-light', 'Ceiling Fan with LED Light 1200mm', 'Ceiling fan with integrated LED light kit', '1200mm ceiling fan with integrated LED light in the centre. 3-speed control. Suitable for rooms where a separate light fixture is not desired.', 'https://images.pexels.com/photos/4224023/pexels-photo-4224023.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 2200, 'per piece', 'unit', 1, 1, 25, '{"sweep": "1200mm", "blades": "3", "led_light": "Yes", "warranty": "2 years"}'::jsonb, 'pickup', true, 20, 14, 3, true),
  (v_lights, v_fans, 'demo-table-fan-400mm', 'Table Fan 400mm (16 inch)', 'Oscillating table fan with 3-speed control', '400mm table fan with oscillation, 3-speed control, and tilt adjustment. Lightweight and portable. Suitable for desks and small rooms.', 'https://images.pexels.com/photos/4224023/pexels-photo-4224023.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 980, 'per piece', 'unit', 1, 1, 60, '{"sweep": "400mm", "type": "Table", "oscillation": "Yes", "speeds": "3"}'::jsonb, 'pickup', true, 30, 0, 0, true);
