  (v_mobiles, v_sp, 'demo-iphone-screen-replacement', 'iPhone 12 Display Assembly', 'OLED display replacement for iPhone 12', 'Original-quality OLED display assembly for iPhone 12. Includes digitizer and frame. Tested before dispatch.', 'https://images.pexels.com/photos/6754839/pexels-photo-6754839.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4200, 'per piece', 'unit', 1, 1, 15, '{"compatibility": "iPhone 12", "type": "OLED", "includes": "Digitizer + Frame"}'::jsonb, 'pickup', true, 10, 8, 2, true),
  (v_mobiles, v_sp, 'demo-samsung-battery', 'Samsung Galaxy M31 Battery', 'Replacement battery 6000mAh for Galaxy M31', 'OEM-equivalent replacement Li-ion battery for Samsung Galaxy M31. 6000mAh capacity. Tested for compatibility.', 'https://images.pexels.com/photos/6754839/pexels-photo-6754839.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 850, 'per piece', 'unit', 1, 1, 30, '{"compatibility": "Galaxy M31", "capacity": "6000mAh", "type": "Li-ion"}'::jsonb, 'pickup', true, 20, 0, 0, true),
  (v_mobiles, v_sp, 'demo-charging-port-micro-usb', 'Micro-USB Charging Port (Universal)', 'Universal micro-USB charging port flex cable', 'Replacement micro-USB charging port flex cable. Universal fit for most Android phones. Soldering required.', 'https://images.pexels.com/photos/6754839/pexels-photo-6754839.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 120, 'per piece', 'unit', 1, 1, 100, '{"type": "Micro-USB", "fit": "Universal", "installation": "Soldering required"}'::jsonb, 'pickup', true, 30, 45, 10, true);
