  (v_mobiles, v_spk, 'demo-bluetooth-speaker-portable', 'Portable Bluetooth Speaker 10W', 'Waterproof portable speaker with 10W output', '10-watt portable Bluetooth 5.0 speaker. IPX7 waterproof rating. 12-hour battery life. Built-in mic for hands-free calls.', 'https://images.pexels.com/photos/1279105/pexels-photo-1279105.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 899, 'per piece', 'unit', 1, 1, 50, '{"output": "10W", "bluetooth": "5.0", "waterproof": "IPX7", "battery": "12 hrs"}'::jsonb, 'pickup', true, 10, 30, 5, true),
  (v_mobiles, v_spk, 'demo-bluetooth-speaker-20w', 'Bluetooth Speaker 20W with RGB', '20W speaker with RGB lighting and deep bass', '20-watt Bluetooth speaker with RGB light effects, deep bass driver, and FM radio. 8-hour playback. USB and SD card support.', 'https://images.pexels.com/photos/1279105/pexels-photo-1279105.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1599, 'per piece', 'unit', 1, 1, 40, '{"output": "20W", "bluetooth": "5.0", "rgb": "Yes", "battery": "8 hrs", "fm_radio": "Yes"}'::jsonb, 'pickup', true, 20, 18, 4, true),
  (v_mobiles, v_spk, 'demo-wired-speaker-2-0', '2.0 Desktop Speakers', 'USB-powered desktop speakers with volume control', 'Compact 2.0 channel desktop speakers. USB-powered with 3.5mm audio jack. Inline volume control. Suitable for PC and laptop.', 'https://images.pexels.com/photos/1279105/pexels-photo-1279105.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 450, 'per piece', 'unit', 1, 1, 80, '{"channels": "2.0", "power": "USB", "connector": "3.5mm", "cable_length": "1.2m"}'::jsonb, 'pickup', true, 30, 5, 2, true);
