  (v_mobiles, v_chg, 'demo-fast-charger-20w-usb-c', '20W Fast Charger USB-C PD', 'Power Delivery 3.0 fast charger for phones and tablets', '20-watt USB-C Power Delivery 3.0 fast charger. Compatible with iPhone 12+ and most Android fast-charge devices. Compact design.', 'https://images.pexels.com/photos/4526473/pexels-photo-4526473.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 599, 'per piece', 'unit', 1, 1, 100, '{"output": "20W", "protocol": "PD 3.0", "port": "USB-C", "input": "100-240V"}'::jsonb, 'pickup', true, 10, 60, 10, true),
  (v_mobiles, v_chg, 'demo-charger-15w-micro-usb', '15W Charger Micro-USB', 'Standard wall charger with micro-USB cable', '15-watt wall charger with built-in micro-USB cable. Suitable for most Android phones and accessories.', 'https://images.pexels.com/photos/4526473/pexels-photo-4526473.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 299, 'per piece', 'unit', 1, 1, 200, '{"output": "15W", "port": "Micro-USB", "input": "100-240V"}'::jsonb, 'pickup', true, 20, 120, 20, true),
  (v_mobiles, v_chg, 'demo-wireless-charger-15w', '15W Wireless Charging Pad', 'Qi-certified wireless charger with LED indicator', 'Qi-certified 15W wireless charging pad. Compatible with all Qi-enabled devices. LED charging indicator. Non-slip surface.', 'https://images.pexels.com/photos/4526473/pexels-photo-4526473.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 750, 'per piece', 'unit', 1, 1, 50, '{"output": "15W", "standard": "Qi", "indicator": "LED", "material": "Silicone + ABS"}'::jsonb, 'pickup', true, 30, 25, 5, true),
  (v_mobiles, v_chg, 'demo-car-charger-dual-usb', 'Dual USB Car Charger 36W', 'Dual-port car charger with fast charge support', '36-watt dual-port USB car charger. One port supports QC 3.0 fast charging. Compact design with LED ring.', 'https://images.pexels.com/photos/4526473/pexels-photo-4526473.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 399, 'per piece', 'unit', 1, 1, 80, '{"output": "36W", "ports": "2", "fast_charge": "QC 3.0", "input": "12-24V"}'::jsonb, 'pickup', true, 40, 0, 0, true);
