  (v_mobiles, v_cc, 'demo-usb-c-cable-1m', 'USB-C to USB-C Cable 1m (60W)', 'Fast-charging USB-C cable with 60W power delivery', '1-metre USB-C to USB-C cable supporting up to 60W power delivery and 480 Mbps data transfer. Braided nylon jacket for durability.', 'https://images.pexels.com/photos/4526473/pexels-photo-4526473.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 249, 'per piece', 'unit', 1, 1, 300, '{"length": "1m", "connectors": "USB-C to USB-C", "power": "60W", "data": "480 Mbps", "jacket": "Braided nylon"}'::jsonb, 'pickup', true, 10, 150, 20, true),
  (v_mobiles, v_cc, 'demo-lightning-cable-1m', 'Lightning to USB-A Cable 1m', 'Apple MFi-certified lightning cable', '1-metre Lightning to USB-A cable. Apple MFi-certified. Sync and charge for iPhone, iPad, and iPod.', 'https://images.pexels.com/photos/4526473/pexels-photo-4526473.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 399, 'per piece', 'unit', 1, 1, 200, '{"length": "1m", "connectors": "Lightning to USB-A", "certified": "MFi", "compatible": "iPhone/iPad"}'::jsonb, 'pickup', true, 20, 90, 15, true),
  (v_mobiles, v_cc, 'demo-micro-usb-cable-1-5m', 'Micro-USB Cable 1.5m (Braided)', 'Durable braided micro-USB charging and data cable', '1.5-metre micro-USB to USB-A cable with braided nylon jacket. Fast charging and data sync. Compatible with most Android devices.', 'https://images.pexels.com/photos/4526473/pexels-photo-4526473.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 179, 'per piece', 'unit', 1, 1, 500, '{"length": "1.5m", "connectors": "Micro-USB to USB-A", "jacket": "Braided nylon"}'::jsonb, 'pickup', true, 30, 3, 5, true);
