  (v_mobiles, v_std, 'demo-phone-stand-aluminium', 'Aluminium Phone Stand', 'Adjustable aluminium desktop phone stand', 'Adjustable aluminium alloy phone stand with silicone pads. Holds phones and small tablets. Folds flat for portability.', 'https://images.pexels.com/photos/4046718/pexels-photo-4046718.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 349, 'per piece', 'unit', 1, 1, 100, '{"material": "Aluminium alloy", "adjustable": "Yes", "foldable": "Yes", "max_width": "85mm"}'::jsonb, 'pickup', true, 10, 40, 8, true),
  (v_mobiles, v_std, 'demo-tablet-floor-stand', 'Tablet Floor Stand (Rolling)', 'Rolling floor stand for tablets and iPads', 'Height-adjustable rolling floor stand for tablets (7-12 inch). Heavy base with wheels. Suitable for presentations and retail displays.', 'https://images.pexels.com/photos/4046718/pexels-photo-4046718.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 1899, 'per piece', 'unit', 1, 1, 15, '{"material": "Steel + plastic", "height": "Adjustable 70-120cm", "wheels": "Yes", "size_range": "7-12 inch"}'::jsonb, 'pickup', true, 20, 10, 2, true);
