  (v_mobiles, v_acc, 'demo-earphones-wired', 'Wired Earphones with Mic (3.5mm)', 'In-ear wired earphones with inline microphone', 'In-ear wired earphones with 3.5mm jack, inline microphone, and volume control. 1.2m cable. Bass-enhanced drivers.', 'https://images.pexels.com/photos/3394650/pexels-photo-3394650.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 199, 'per piece', 'unit', 1, 1, 300, '{"type": "In-ear", "connector": "3.5mm", "mic": "Yes", "cable": "1.2m"}'::jsonb, 'pickup', true, 10, 200, 30, true),
  (v_mobiles, v_acc, 'demo-power-bank-10000', 'Power Bank 10000mAh 18W PD', 'Fast-charging power bank with dual USB output', '10000mAh power bank with 18W PD fast charging. Dual USB-A output + 1 USB-C input/output. LED battery indicator. Compact aluminium body.', 'https://images.pexels.com/photos/3394650/pexels-photo-3394650.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 899, 'per piece', 'unit', 1, 1, 80, '{"capacity": "10000mAh", "output": "18W PD", "ports": "2x USB-A + 1x USB-C", "body": "Aluminium"}'::jsonb, 'pickup', true, 20, 35, 5, true),
  (v_mobiles, v_acc, 'demo-screen-protector-tempered', 'Tempered Glass Screen Protector (Universal)', '9H tempered glass screen protector with oleophobic coating', 'Universal 9H tempered glass screen protector. 0.3mm thickness. Oleophobic coating resists fingerprints. Includes installation kit.', 'https://images.pexels.com/photos/3394650/pexels-photo-3394650.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 99, 'per piece', 'unit', 1, 1, 500, '{"hardness": "9H", "thickness": "0.3mm", "coating": "Oleophobic", "includes": "Installation kit"}'::jsonb, 'pickup', true, 30, 0, 0, true);
