  (v_solar, v_panels, 'demo-solar-panel-300w-mono', 'Monocrystalline Solar Panel 300W', 'High-efficiency mono panel for rooftop installation', '300-watt monocrystalline solar panel with 21% efficiency. IP67 junction box. 25-year power output warranty. Suitable for residential rooftop systems.', 'https://images.pexels.com/photos/29206488/pexels-photo-29206488.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 8500, 'per panel', 'unit', 1, 1, 20, '{"type": "Monocrystalline", "wattage": "300W", "efficiency": "21%", "warranty": "25 years", "junction_box": "IP67"}'::jsonb, 'consultation', true, 10, 12, 2, true),
  (v_solar, v_panels, 'demo-solar-panel-450w-mono', 'Monocrystalline Solar Panel 450W', 'High-output panel for larger rooftop systems', '450-watt monocrystalline half-cut cell solar panel. 21.5% efficiency. Better low-light performance. 25-year warranty.', 'https://images.pexels.com/photos/29206488/pexels-photo-29206488.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 12500, 'per panel', 'unit', 1, 1, 15, '{"type": "Monocrystalline", "wattage": "450W", "efficiency": "21.5%", "cell_type": "Half-cut", "warranty": "25 years"}'::jsonb, 'consultation', true, 20, 8, 1, true),
  (v_solar, v_panels, 'demo-solar-panel-150w-poly', 'Polycrystalline Solar Panel 150W', 'Budget-friendly panel for small installations', '150-watt polycrystalline solar panel. 17% efficiency. Suitable for small off-grid systems, solar lighting, and battery charging.', 'https://images.pexels.com/photos/29206488/pexels-photo-29206488.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 4200, 'per panel', 'unit', 1, 1, 30, '{"type": "Polycrystalline", "wattage": "150W", "efficiency": "17%", "warranty": "20 years"}'::jsonb, 'consultation', true, 30, 0, 0, true);
