  (v_solar, v_inv, 'demo-solar-inverter-3kva-pwm', 'Solar PWM Inverter 3kVA', 'PWM solar inverter for small rooftop systems', '3kVA PWM solar inverter with built-in charge controller. Pure sine wave output. LCD display. Suitable for 2-3 kW rooftop systems.', 'https://images.pexels.com/photos/3719005/pexels-photo-3719005.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 14000, 'per piece', 'unit', 1, 1, 10, '{"capacity": "3kVA", "type": "PWM", "waveform": "Pure sine wave", "display": "LCD"}'::jsonb, 'consultation', true, 10, 6, 1, true),
  (v_solar, v_inv, 'demo-solar-inverter-5kva-mppt', 'Solar MPPT Inverter 5kVA', 'MPPT solar inverter with dual MPPT tracking', '5kVA MPPT solar inverter with dual MPPT tracking for maximum power harvest. Pure sine wave. Wi-Fi monitoring. Suitable for 4-6 kW systems.', 'https://images.pexels.com/photos/3719005/pexels-photo-3719005.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 28000, 'per piece', 'unit', 1, 1, 8, '{"capacity": "5kVA", "type": "MPPT", "mppt_trackers": "2", "waveform": "Pure sine wave", "monitoring": "Wi-Fi"}'::jsonb, 'consultation', true, 20, 4, 1, true),
  (v_solar, v_inv, 'demo-solar-battery-150ah', 'Solar Battery 150Ah Tall Tubular', 'Tall tubular battery for solar storage systems', '150Ah tall tubular battery designed for solar applications. C10 rating. Low maintenance. Suitable for residential solar storage.', 'https://images.pexels.com/photos/3719005/pexels-photo-3719005.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 13500, 'per piece', 'unit', 1, 1, 15, '{"capacity": "150Ah", "type": "Tall tubular", "rating": "C10", "warranty": "5 years", "maintenance": "Low"}'::jsonb, 'consultation', true, 30, 10, 2, true);
