/*
# Insert temporary demo products for catalogue testing (corrected)

All products marked is_demo = true. See previous migration attempt for full docs.
This version correctly uses category_id for the category and subcategory_id for the subcategory.
*/

DO $$
DECLARE
  v_cables uuid; v_lights uuid; v_mobiles uuid; v_solar uuid;
  v_cables_dom uuid; v_cables_ind uuid;
  v_lights_dom uuid; v_lights_ind uuid; v_fans uuid;
  v_sp uuid; v_spk uuid; v_chg uuid; v_cc uuid; v_std uuid; v_acc uuid;
  v_panels uuid; v_inv uuid;
BEGIN
  SELECT id INTO v_cables FROM categories WHERE slug = 'cables';
  SELECT id INTO v_lights FROM categories WHERE slug = 'lights';
  SELECT id INTO v_mobiles FROM categories WHERE slug = 'mobiles';
  SELECT id INTO v_solar FROM categories WHERE slug = 'solar';

  SELECT id INTO v_cables_dom FROM subcategories WHERE category_id = v_cables AND slug = 'domestic';
  SELECT id INTO v_cables_ind FROM subcategories WHERE category_id = v_cables AND slug = 'industrial';
  SELECT id INTO v_lights_dom FROM subcategories WHERE category_id = v_lights AND slug = 'domestic';
  SELECT id INTO v_lights_ind FROM subcategories WHERE category_id = v_lights AND slug = 'industrial';
  SELECT id INTO v_fans FROM subcategories WHERE category_id = v_lights AND slug = 'fans';
  SELECT id INTO v_sp FROM subcategories WHERE category_id = v_mobiles AND slug = 'spare-parts';
  SELECT id INTO v_spk FROM subcategories WHERE category_id = v_mobiles AND slug = 'speakers';
  SELECT id INTO v_chg FROM subcategories WHERE category_id = v_mobiles AND slug = 'chargers';
  SELECT id INTO v_cc FROM subcategories WHERE category_id = v_mobiles AND slug = 'charging-cables';
  SELECT id INTO v_std FROM subcategories WHERE category_id = v_mobiles AND slug = 'stands';
  SELECT id INTO v_acc FROM subcategories WHERE category_id = v_mobiles AND slug = 'accessories';
  SELECT id INTO v_panels FROM subcategories WHERE category_id = v_solar AND slug = 'panels';
  SELECT id INTO v_inv FROM subcategories WHERE category_id = v_solar AND slug = 'inverters-batteries';

  -- CABLES — DOMESTIC

  -- CABLES — INDUSTRIAL

  -- LIGHTS & FANS — DOMESTIC LIGHTS

  -- LIGHTS & FANS — INDUSTRIAL LIGHTS

  -- LIGHTS & FANS — FANS

  -- ELECTRONICS — SPARE PARTS

  -- ELECTRONICS — SPEAKERS

  -- ELECTRONICS — CHARGERS

  -- ELECTRONICS — CHARGING CABLES

  -- ELECTRONICS — STANDS

  -- ELECTRONICS — ACCESSORIES

  -- SOLAR — PANELS

  -- SOLAR — INVERTERS & BATTERIES

END $$;
